-- ============================================================================
-- superi.ge — ბრენდები: დუბლიკატების გაერთიანება, სუფთა მისამართები,
-- სათაური და აღწერა ყველა ბრენდის გვერდს (Google-ის მოთხოვნებით).
-- 1) Blackview (22 პროდ., ლოგოს გარეშე) → BLACKVIEW (ლოგოთი)
--    Nothing (2 პროდ., ლოგოს გარეშე)  → NOTHING PHONE (ლოგოთი და აღწერით)
--    პროდუქტები გადადის დარჩენილ ბრენდზე, ძველი მისამართი 301-ით გადამისამართდება.
-- 2) Keter და Rattan იღებენ სუფთა მისამართს (/keter/, /rattan/) -ka-ს ნაცვლად.
-- 3) ყველა ბრენდს: სათაური „[ბრენდი] — საუკეთესო ფასები | Superi.ge“ და აღწერა.
-- ცვლილებამდე წაშლილი ჩანაწერების ასლი ინახება superi_bk_* ცხრილებში (დაბრუნებისთვის).
-- ============================================================================

SET NAMES utf8mb4;

-- 0) ბრენდის გვერდების SEO-ტიპის და გადამისამართების ფორმატის დადგენა
SET @et := (SELECT s.type FROM cscart_seo_names s JOIN cscart_product_feature_variant_descriptions vd ON vd.variant_id = s.object_id AND vd.lang_code = 'ka' WHERE s.name = 'samsung' AND s.lang_code = 'ka' AND vd.variant = 'SAMSUNG' LIMIT 1);
SET @f := (SELECT src FROM cscart_seo_redirects WHERE TRIM(BOTH '/' FROM src) = 'category-15' LIMIT 1);
SET @pre := IF(@f IS NULL OR LEFT(@f,1) = '/', '/', '');
SET @post := IF(@f IS NULL OR RIGHT(@f,1) = '/', '/', '');
SET @k1 := (SELECT s.object_id FROM cscart_seo_names s JOIN cscart_product_feature_variant_descriptions vd ON vd.variant_id = s.object_id AND vd.lang_code = 'ka' WHERE s.type = @et AND s.lang_code = 'ka' AND s.name = 'blackview' AND LOWER(REPLACE(vd.variant, ' ', '')) = 'blackview' LIMIT 1);
SET @d1 := (SELECT s.object_id FROM cscart_seo_names s JOIN cscart_product_feature_variant_descriptions vd ON vd.variant_id = s.object_id AND vd.lang_code = 'ka' WHERE s.type = @et AND s.lang_code = 'ka' AND s.name = 'blackview-ka' AND LOWER(REPLACE(vd.variant, ' ', '')) = 'blackview' LIMIT 1);
SET @k2 := (SELECT s.object_id FROM cscart_seo_names s JOIN cscart_product_feature_variant_descriptions vd ON vd.variant_id = s.object_id AND vd.lang_code = 'ka' WHERE s.type = @et AND s.lang_code = 'ka' AND s.name = 'nothing-phone' AND LOWER(REPLACE(vd.variant, ' ', '')) = 'nothingphone' LIMIT 1);
SET @d2 := (SELECT s.object_id FROM cscart_seo_names s JOIN cscart_product_feature_variant_descriptions vd ON vd.variant_id = s.object_id AND vd.lang_code = 'ka' WHERE s.type = @et AND s.lang_code = 'ka' AND s.name = 'nothing' AND LOWER(REPLACE(vd.variant, ' ', '')) = 'nothing' LIMIT 1);
SET @kf1 := (SELECT feature_id FROM cscart_product_feature_variants WHERE variant_id = @k1);
SET @kf2 := (SELECT feature_id FROM cscart_product_feature_variants WHERE variant_id = @k2);

-- 1) დუბლიკატების ასლი (დაბრუნებისთვის)
CREATE TABLE IF NOT EXISTS superi_bk_product_features_values AS SELECT * FROM cscart_product_features_values WHERE variant_id IN (@d1, @d2);
CREATE TABLE IF NOT EXISTS superi_bk_product_feature_variants AS SELECT * FROM cscart_product_feature_variants WHERE variant_id IN (@d1, @d2);
CREATE TABLE IF NOT EXISTS superi_bk_product_feature_variant_descriptions AS SELECT * FROM cscart_product_feature_variant_descriptions WHERE variant_id IN (@d1, @d2);
CREATE TABLE IF NOT EXISTS superi_bk_brand_seo AS SELECT * FROM cscart_seo_names WHERE type = @et AND object_id IN (@d1, @d2);

-- 1) blackview-ka → გაერთიანება
UPDATE IGNORE cscart_product_features_values SET variant_id = @k1, feature_id = @kf1 WHERE variant_id = @d1 AND @k1 IS NOT NULL AND @d1 IS NOT NULL AND @k1 <> @d1;
DELETE FROM cscart_product_features_values WHERE variant_id = @d1 AND @k1 IS NOT NULL AND @d1 IS NOT NULL AND @k1 <> @d1;
DELETE FROM cscart_product_feature_variant_descriptions WHERE variant_id = @d1 AND @k1 IS NOT NULL AND @d1 IS NOT NULL AND @k1 <> @d1;
DELETE FROM cscart_product_feature_variants WHERE variant_id = @d1 AND @k1 IS NOT NULL AND @d1 IS NOT NULL AND @k1 <> @d1;
DELETE FROM cscart_images_links WHERE object_type = 'feature_variant' AND object_id = @d1 AND @k1 IS NOT NULL AND @d1 IS NOT NULL AND @k1 <> @d1;
DELETE FROM cscart_seo_names WHERE type = @et AND object_id = @d1 AND @k1 IS NOT NULL AND @d1 IS NOT NULL AND @k1 <> @d1;
UPDATE cscart_seo_redirects SET object_id = @k1 WHERE type = @et AND object_id = @d1 AND @k1 IS NOT NULL AND @d1 IS NOT NULL AND @k1 <> @d1;
DELETE FROM cscart_seo_redirects WHERE company_id = 1 AND TRIM(BOTH '/' FROM src) = 'blackview-ka' AND @k1 IS NOT NULL AND @d1 IS NOT NULL AND @k1 <> @d1;
INSERT IGNORE INTO cscart_seo_redirects (src, type, object_id, lang_code, company_id) SELECT CONCAT(@pre, 'blackview-ka', @post), @et, @k1, 'ka', 1 FROM DUAL WHERE @k1 IS NOT NULL AND @d1 IS NOT NULL AND @k1 <> @d1;

-- 1) nothing → გაერთიანება
UPDATE IGNORE cscart_product_features_values SET variant_id = @k2, feature_id = @kf2 WHERE variant_id = @d2 AND @k2 IS NOT NULL AND @d2 IS NOT NULL AND @k2 <> @d2;
DELETE FROM cscart_product_features_values WHERE variant_id = @d2 AND @k2 IS NOT NULL AND @d2 IS NOT NULL AND @k2 <> @d2;
DELETE FROM cscart_product_feature_variant_descriptions WHERE variant_id = @d2 AND @k2 IS NOT NULL AND @d2 IS NOT NULL AND @k2 <> @d2;
DELETE FROM cscart_product_feature_variants WHERE variant_id = @d2 AND @k2 IS NOT NULL AND @d2 IS NOT NULL AND @k2 <> @d2;
DELETE FROM cscart_images_links WHERE object_type = 'feature_variant' AND object_id = @d2 AND @k2 IS NOT NULL AND @d2 IS NOT NULL AND @k2 <> @d2;
DELETE FROM cscart_seo_names WHERE type = @et AND object_id = @d2 AND @k2 IS NOT NULL AND @d2 IS NOT NULL AND @k2 <> @d2;
UPDATE cscart_seo_redirects SET object_id = @k2 WHERE type = @et AND object_id = @d2 AND @k2 IS NOT NULL AND @d2 IS NOT NULL AND @k2 <> @d2;
DELETE FROM cscart_seo_redirects WHERE company_id = 1 AND TRIM(BOTH '/' FROM src) = 'nothing' AND @k2 IS NOT NULL AND @d2 IS NOT NULL AND @k2 <> @d2;
INSERT IGNORE INTO cscart_seo_redirects (src, type, object_id, lang_code, company_id) SELECT CONCAT(@pre, 'nothing', @post), @et, @k2, 'ka', 1 FROM DUAL WHERE @k2 IS NOT NULL AND @d2 IS NOT NULL AND @k2 <> @d2;

-- 2) Keter და Rattan: პროდუქტს აღწერითი მისამართი, ბრენდს სუფთა
UPDATE cscart_seo_names SET name = 'baghis-avejis-komplekti-keter' WHERE type = 'p' AND lang_code = 'ka' AND name = 'keter' AND NOT EXISTS (SELECT 1 FROM (SELECT name FROM cscart_seo_names WHERE name = 'baghis-avejis-komplekti-keter') t);
SET @b := (SELECT object_id FROM cscart_seo_names WHERE type = @et AND lang_code = 'ka' AND name = 'keter-ka' LIMIT 1);
SET @free := (SELECT COUNT(*) FROM cscart_seo_names WHERE name = 'keter') = 0;
DELETE FROM cscart_seo_redirects WHERE company_id = 1 AND TRIM(BOTH '/' FROM src) IN ('keter-ka', 'keter') AND @b IS NOT NULL AND @free;
INSERT IGNORE INTO cscart_seo_redirects (src, type, object_id, lang_code, company_id) SELECT CONCAT(@pre, 'keter-ka', @post), @et, @b, 'ka', 1 FROM DUAL WHERE @b IS NOT NULL AND @free;
UPDATE cscart_seo_names SET name = 'keter' WHERE type = @et AND lang_code = 'ka' AND name = 'keter-ka' AND @free;

UPDATE cscart_seo_names SET name = 'naturaluri-ratanis-baghis-avejis-nakrebi' WHERE type = 'p' AND lang_code = 'ka' AND name = 'rattan' AND NOT EXISTS (SELECT 1 FROM (SELECT name FROM cscart_seo_names WHERE name = 'naturaluri-ratanis-baghis-avejis-nakrebi') t);
SET @b := (SELECT object_id FROM cscart_seo_names WHERE type = @et AND lang_code = 'ka' AND name = 'rattan-ka' LIMIT 1);
SET @free := (SELECT COUNT(*) FROM cscart_seo_names WHERE name = 'rattan') = 0;
DELETE FROM cscart_seo_redirects WHERE company_id = 1 AND TRIM(BOTH '/' FROM src) IN ('rattan-ka', 'rattan') AND @b IS NOT NULL AND @free;
INSERT IGNORE INTO cscart_seo_redirects (src, type, object_id, lang_code, company_id) SELECT CONCAT(@pre, 'rattan-ka', @post), @et, @b, 'ka', 1 FROM DUAL WHERE @b IS NOT NULL AND @free;
UPDATE cscart_seo_names SET name = 'rattan' WHERE type = @et AND lang_code = 'ka' AND name = 'rattan-ka' AND @free;

-- 3) ყველა ბრენდის სათაური და აღწერა
UPDATE cscart_product_feature_variant_descriptions vd JOIN cscart_product_feature_variants v ON v.variant_id = vd.variant_id JOIN cscart_product_features f ON f.feature_id = v.feature_id AND f.feature_type = 'E'
SET vd.page_title = CONCAT(CASE WHEN vd.variant LIKE '%|%' THEN CONCAT(TRIM(SUBSTRING_INDEX(vd.variant, '|', 1)), ' (', TRIM(SUBSTRING_INDEX(vd.variant, '|', -1)), ')') WHEN BINARY vd.variant = BINARY LOWER(vd.variant) THEN CONCAT(UPPER(LEFT(vd.variant, 1)), SUBSTRING(vd.variant, 2)) ELSE vd.variant END, ' — საუკეთესო ფასები | Superi.ge'),
    vd.meta_description = CONCAT(CASE WHEN vd.variant LIKE '%|%' THEN TRIM(SUBSTRING_INDEX(vd.variant, '|', 1)) WHEN BINARY vd.variant = BINARY LOWER(vd.variant) THEN CONCAT(UPPER(LEFT(vd.variant, 1)), SUBSTRING(vd.variant, 2)) ELSE vd.variant END, '-ის პროდუქცია Superi.ge-ზე: ✓ ნაწილ-ნაწილ გადახდა ✓ უფასო მიწოდება თბილისში 100₾-დან ✓ მიწოდება მთელ საქართველოში.')
WHERE vd.lang_code = 'ka' AND TRIM(vd.variant) <> '';

-- 4) შემოწმება
SELECT @et AS seo_type, @k1 AS blackview, @d1 AS blackview_ka, @k2 AS nothing_phone, @d2 AS nothing;
SELECT COUNT(*) AS brands, SUM(vd.page_title LIKE '% — საუკეთესო ფასები | Superi.ge') AS titles_ok, SUM(vd.meta_description LIKE '%ნაწილ-ნაწილ გადახდა%') AS descriptions_ok FROM cscart_product_feature_variant_descriptions vd JOIN cscart_product_feature_variants v ON v.variant_id = vd.variant_id JOIN cscart_product_features f ON f.feature_id = v.feature_id AND f.feature_type = 'E' WHERE vd.lang_code = 'ka';

