-- UPDATE cscart_product_feature_variant_descriptions vd JOIN cscart_seo_names s ON s.object_id = vd.variant_id AND s.type = @et AND s.name = 'fujiyama' SET vd.page_title = 'FUJIYAMA | Superi.ge', vd.meta_description = 'FUJIYAMA გაზის გამათბობლები – მაღალი ხარისხი, ეფექტურობა და თანამედროვე დიზაინი. ჩვენი პროდუქტი გაწვდით მაქსიმალურ სითბოს მინიმალური გაზის მოხმარებით. შეარჩიეთ FUJIYAMA და უზრუნველყავით სასურველი კომფორტი და სითბო თქვენს სივრცეში' WHERE vd.lang_code = 'ka';
