-- UPDATE cscart_product_feature_variant_descriptions vd JOIN cscart_seo_names s ON s.object_id = vd.variant_id AND s.type = @et AND s.name = 'riken' SET vd.page_title = 'RIKEN ბრენდის საბურავები საუკეთესო ფასად | SUPERI.GE', vd.meta_description = 'SUPERI.GE გთავაზობთ RIKEN ბრენდის საბურავების ფართო არჩევანს, რომელიც აერთიანებს მდგრადობას, სანდოობას და ეფექტურობის მაღალ სტანდარტებს. მოძებნეთ იდეალური საბურავები საუკეთესო ფასად.' WHERE vd.lang_code = 'ka';
-- UPDATE cscart_product_feature_variant_descriptions vd JOIN cscart_seo_names s ON s.object_id = vd.variant_id AND s.type = @et AND s.name = 'nordictrack' SET vd.page_title = 'NordicTrack სარბენი ბილიკები და ფიტნეს ტრენაჟორები | SUPERI.GE', vd.meta_description = 'შეიძინე NordicTrack-ის სარბენი ბილიკები და ფიტნეს ტრენაჟორები SUPER-ში საუკეთესო ფასად. პრემიუმ ხარისხი, კომფორტული ვარჯიში, მარტივი შეძენა და სწრაფი მიწოდება.' WHERE vd.lang_code = 'ka';
-- UPDATE cscart_product_feature_variant_descriptions vd JOIN cscart_seo_names s ON s.object_id = vd.variant_id AND s.type = @et AND s.name = 'galanz' SET vd.page_title = 'GALANZ | Superi.ge | აღმოაჩინე საუკეთესო შეთავაზებები', vd.meta_description = 'GALANZ არის წამყვანი ტექნიკის მწარმოებელი ბრენდი, რომელიც ცნობილია თავისი მაღალ ტექნოლოგიური და ხარისხიანი პროდუქციით. ჩვენ უზრუნველვყოფთ მომხმარებლისთვის თანამედროვე, ეფექტურ და სტილურ მოწყობილობებს, რომლებიც მიმართულია ყოველდღიური კომფორტისა და სამუშაო ' WHERE vd.lang_code = 'ka';
-- UPDATE cscart_product_feature_variant_descriptions vd JOIN cscart_seo_names s ON s.object_id = vd.variant_id AND s.type = @et AND s.name = 'elenberg' SET vd.page_title = 'ELENBERG | Superi.ge', vd.meta_description = 'შეიძინეთ ELENBERG ის პროდუქცია საუკეთესო ფასად. მიიღეთ 2 წლიანი გარანტია და უფასო მიწოდება საქართველოს მასშტაბით' WHERE vd.lang_code = 'ka';
-- UPDATE cscart_product_feature_variant_descriptions vd JOIN cscart_seo_names s ON s.object_id = vd.variant_id AND s.type = @et AND s.name = 'viewsonic' SET vd.page_title = 'ViewSonic | Superi.ge', vd.meta_description = 'იხილეთ ViewSonic-ის ბრენდის ინოვაციური მონიტორები,პროექტროები და სხვადასხვა პროდუქცა, რომლებიც იძლევა უპრეცედენტო სურათის ხარისხს და გამოსახულების სიზუსტეს. მაღალხარისხიანი ტექნოლოგიით, გეიმინგ პროდუქტების ფართო არჩევანით, ViewSonic ქმნის იდეალურ გადაწყვე' WHERE vd.lang_code = 'ka';
-- UPDATE cscart_product_feature_variant_descriptions vd JOIN cscart_seo_names s ON s.object_id = vd.variant_id AND s.type = @et AND s.name = 'sokany' SET vd.page_title = 'SOKANY | Superi.ge', vd.meta_description = 'შეიძინე SOKANY ის ბრენდის გამორჩეული პროდუქცია SUPER ფასად.' WHERE vd.lang_code = 'ka';
