-- UPDATE cscart_product_feature_variant_descriptions vd JOIN cscart_seo_names s ON s.object_id = vd.variant_id AND s.type = @et AND s.name = 'ugreen' SET vd.page_title = '', vd.meta_description = 'UGREEN გთავაზობთ მაღალი ხარისხის ტექნიკურ აქსესუარებს, როგორიცაა კაბელები, დამტენები და ადაპტერები, რაც უზრუნველყოფს თქვენი მოწყობილობების სრულფასოვან მუშაობას' WHERE vd.lang_code = 'ka';
-- UPDATE cscart_product_feature_variant_descriptions vd JOIN cscart_seo_names s ON s.object_id = vd.variant_id AND s.type = @et AND s.name = 'canyon' SET vd.page_title = 'CANYON', vd.meta_description = 'CANYON გთავაზობთ ინოვაციურ და ხარისხიან ტექნოლოგიურ აქსესუარებს, როგორიცაა კომპიუტერული periferიული მოწყობილობები, სმარტფონის აქსესუარები და ავტომობილური ტექნიკა. ბრენდი გამორჩეულია თავისი თანამედროვე დიზაინით, საიმედოობითა და მომხმარებელზე ორიენტირებული ' WHERE vd.lang_code = 'ka';
-- UPDATE cscart_product_feature_variant_descriptions vd JOIN cscart_seo_names s ON s.object_id = vd.variant_id AND s.type = @et AND s.name = 'thomson' SET vd.page_title = 'Thomson', vd.meta_description = 'THOMSON - ის ბრენდი 1893 წელს საფრანგეთში დაარსდა, მას შემდეგ 130 წლიანი გამოცდილება დააგროვა და დღეს-დღეისობით ეს ბრენდი მოწინავე პოზიციას იკავებს ბაზარზე. ბრენდის მთავარი მიზანია: უახლესი ტექნოლოგიების შემუშავება და ის რომ მათი პროდუქცია ყველასათვის იყო' WHERE vd.lang_code = 'ka';
-- UPDATE cscart_product_feature_variant_descriptions vd JOIN cscart_seo_names s ON s.object_id = vd.variant_id AND s.type = @et AND s.name = 'wokin' SET vd.page_title = '', vd.meta_description = '' WHERE vd.lang_code = 'ka';
-- UPDATE cscart_product_feature_variant_descriptions vd JOIN cscart_seo_names s ON s.object_id = vd.variant_id AND s.type = @et AND s.name = 'onvo' SET vd.page_title = '', vd.meta_description = 'ONVO - თანამედროვე ტექნიკის მწარმოებელი ბრენდი, რომელიც გთავაზობთ ხარისხიან და ინოვაციურ ელექტრონიკას. აღმოაჩინეთ ONVO-ს ტელევიზორები, სმარტ მოწყობილობები და სხვა საყოფაცხოვრებო ტექნიკა.' WHERE vd.lang_code = 'ka';
-- UPDATE cscart_product_feature_variant_descriptions vd JOIN cscart_seo_names s ON s.object_id = vd.variant_id AND s.type = @et AND s.name = 'chiq' SET vd.page_title = '', vd.meta_description = 'ChiQ — ინოვაციური ტექნოლოგიების ბრენდი, რომელიც გთავაზობთ WiFi-ით მართვად ჭკვიან კონდიციონერებს იონიზაციის, თვითწმენდისა და ენერგოეფექტური ფუნქციებით. აღმოაჩინე ხარისხი და სმარტ კომფორტი CHiQ-თან ერთად.' WHERE vd.lang_code = 'ka';
-- UPDATE cscart_product_feature_variant_descriptions vd JOIN cscart_seo_names s ON s.object_id = vd.variant_id AND s.type = @et AND s.name = 'lux-garden' SET vd.page_title = '', vd.meta_description = 'LUX GARDEN გთავაზობთ ხარისხიან და გამძლე ბაღის ტექნიკას – ბენზო სათიბელებს, ტრიმერებსა და სხვა მექანიზმებს, რომელიც შესაფერისია როგორც პროფესიონალური, ასევე საყოფაცხოვრებო გამოყენებისთვის' WHERE vd.lang_code = 'ka';
