-- UPDATE cscart_product_feature_variant_descriptions vd JOIN cscart_seo_names s ON s.object_id = vd.variant_id AND s.type = @et AND s.name = 'msi-gaming' SET vd.page_title = 'MSI Gaming ლეპტოპები და კომპიუტერები', vd.meta_description = 'MSI – ლიდერი ინოვაციური ტექნოლოგიების სამყაროში MSI (Micro-Star International) არის გლობალურად აღიარებული ბრენდი, რომელიც სპეციალიზდება მაღალტექნოლოგიური და წარმადობის მხრივ მოწინავე პროდუქციის შექმნაში.' WHERE vd.lang_code = 'ka';
-- UPDATE cscart_product_feature_variant_descriptions vd JOIN cscart_seo_names s ON s.object_id = vd.variant_id AND s.type = @et AND s.name = 'karma' SET vd.page_title = '', vd.meta_description = 'Karma-ის გაზის გამათბობლები უზრუნველყოფს ეფექტურ და უსაფრთხო გათბობას. მაღალი ხარისხის მასალებით დამზადებული მოდელები გამოირჩევიან ენერგოეფექტურობით, მარტივი მართვით და ხანგრძლივი საიმედოობით' WHERE vd.lang_code = 'ka';
-- UPDATE cscart_product_feature_variant_descriptions vd JOIN cscart_seo_names s ON s.object_id = vd.variant_id AND s.type = @et AND s.name = 'thermaltake' SET vd.page_title = '', vd.meta_description = 'Thermaltake წარმოადგენს მაღალი ხარისხის გეიმერული და ПК კომპონენტების მწარმოებელს: კორპუსები, კვების ბლოკები, ქულერები, RGB განათება და აქსესუარები, შექმნილი შესრულებაზე, გამძლეობასა და ესთეტიკაზე ზრუნვით' WHERE vd.lang_code = 'ka';
-- UPDATE cscart_product_feature_variant_descriptions vd JOIN cscart_seo_names s ON s.object_id = vd.variant_id AND s.type = @et AND s.name = 'urevo' SET vd.page_title = 'UREVO სარბენი ბილიკები – მაღალი ხარისხი, ჩუმი მუშაობა და დასაკეცი დიზაინი', vd.meta_description = 'UREVO გთავაზობთ სანდო და ჩუმად მომუშავე სარბენ ბილიკებს, ძლიერი ძრავით, ჩასაკეცი დიზაინით, მრავალ რეჟიმითა და მაღალი დატვირთვის შესაძლებლობით. იდეალურია სახლში ვარჯიშისთვის, უზრუნველყოფს კომფორტს, უსაფრთხოებას და გამძლეობას' WHERE vd.lang_code = 'ka';
-- UPDATE cscart_product_feature_variant_descriptions vd JOIN cscart_seo_names s ON s.object_id = vd.variant_id AND s.type = @et AND s.name = 'kingsmith' SET vd.page_title = 'Kingsmith სარბენი ბილიკები – სმარტ ჩასაკეცი დიზაინი და მაღალი ხარისხი | Superi.ge', vd.meta_description = 'Kingsmith გთავაზობთ ინოვაციურ და ჩუმად მომუშავე სარბენ ბილიკებს, ჩასაკეცი დიზაინით, ჭკვიანი კონტროლით, მაღალი დატვირთვის შესაძლებლობითა და კომფორტული ვარჯიშისთვის შექმნილი სტრუქტურით. შეუხამეთ ხარისხი, სიმშვიდე და თანამედროვე ფიტნესი სახლში' WHERE vd.lang_code = 'ka';
-- UPDATE cscart_product_feature_variant_descriptions vd JOIN cscart_seo_names s ON s.object_id = vd.variant_id AND s.type = @et AND s.name = 'thermex' SET vd.page_title = 'Thermex – წყლის გამაცხელებლები, ელექტრო ბოილერები და გამათბობლები | Superi.ge', vd.meta_description = 'THERMEX – სანდო და ენერგოეფექტური წყლის გამაცხელებლები, ბრტყელი და კლასიკური ბოილერები, სწრაფი გახურება, ხანგრძლივი რესურსი და მაღალი ხარისხი. შეიძინე Thermex-ის ოფიციალური პროდუქცია საუკეთესო ფასად Superi.ge-ზე' WHERE vd.lang_code = 'ka';
