-- UPDATE cscart_product_feature_variant_descriptions vd JOIN cscart_seo_names s ON s.object_id = vd.variant_id AND s.type = @et AND s.name = 'energizer' SET vd.page_title = 'Energizer – აკუმულატორები', vd.meta_description = 'Energizer აკუმულატორები და მაღალი ხარისხის ელემენტები Superi.ge-ზე. მეტი ენერგია, ხანგრძლივი მუშაობა და საიმედოობა ყველა მოწყობილობისთვის. ઝડપી მიწოდება საქართველოს მასშტაბით' WHERE vd.lang_code = 'ka';
