-- UPDATE cscart_product_feature_variant_descriptions vd JOIN cscart_seo_names s ON s.object_id = vd.variant_id AND s.type = @et AND s.name = 'samsung' SET vd.page_title = 'SAMSUNG | Superi.ge | აღმოაჩინე საუკეთესო შეთავაზებები', vd.meta_description = 'Samsung - ინოვაციის და ტექნოლოგიური ლიდერობა Samsung არის გლობალური ბრენდი, რომელიც ცნობილია თავისი უმაღლესი ხარისხის და ინოვაციური ტექნოლოგიური პროდუქტებით. ჩვენ გთავაზობთ ფართო სპექტრს თანამედროვე ტექნიკისა და ელექტრონიკის, რომელიც შექმნილია იმისათვი' WHERE vd.lang_code = 'ka';
