-- UPDATE cscart_product_feature_variant_descriptions vd JOIN cscart_seo_names s ON s.object_id = vd.variant_id AND s.type = @et AND s.name = 'dreame' SET vd.page_title = '', vd.meta_description = 'DREAME გთავაზობთ ფართო სპექტრის ჭკვიან საყოფაცხოვრებო მოწყობილობებს: რობოტი და უსადენო მტვერსასრუტები, ჭკვიანი ფენები, ჰაერის ფილტრები, იონიზატორები და სხვა ინოვაციური ტექნიკა. მარტივი, ეფექტური და მაღალი ხარისხი თქვენი სახლისა და პირადი მოვლისთვის' WHERE vd.lang_code = 'ka';
-- UPDATE cscart_product_feature_variant_descriptions vd JOIN cscart_seo_names s ON s.object_id = vd.variant_id AND s.type = @et AND s.name = 'inno3d' SET vd.page_title = 'INNO3D ვიდეო ბარათები – NVIDIA GeForce RTX გრაფიკული ბარათები | Superi', vd.meta_description = 'INNO3D ვიდეო ბარათები NVIDIA GeForce RTX სერიით. ძლიერი გრაფიკული ბარათები გეიმინგისთვის, ვიდეო მონტაჟისთვის და პროფესიონალური გამოყენებისთვის. შეარჩიეთ INNO3D გრაფიკული ბარათი საუკეთესო ფასად.' WHERE vd.lang_code = 'ka';
-- UPDATE cscart_product_feature_variant_descriptions vd JOIN cscart_seo_names s ON s.object_id = vd.variant_id AND s.type = @et AND s.name = 'marazzi' SET vd.page_title = 'MARAZZI ტექნიკა საქართველოში | იტალიური ხარისხი და თანამედროვე საყოფაცხოვრებო ტექნიკა', vd.meta_description = 'აღმოაჩინეთ MARAZZI-ს თანამედროვე საყოფაცხოვრებო და კომერციული ტექნიკა Superi.ge-ზე. მაცივრები, სარეცხი მანქანები, კონდიციონერები, გამაგრილებლები და სხვა ტექნიკა ხარისხით, სტილითა და სანდოობით.' WHERE vd.lang_code = 'ka';
